const form = $input.first().json;

const title = form['Content Title'] || 'Untitled';
const content = form['Original Content'] || '';
const niche = form['Content Niche'] || 'Project Management & Leadership';
const audience = form['Target Audience'] || 'professionals and leaders';
const postToBuffer = form['Post to Social Media?'] === 'Yes - schedule via Buffer';

return [{
  json: { title, content, niche, audience, postToBuffer }
}];

