const response = $input.first().json;
const text = response.content?.[0]?.text || '{}';

let parsed;
try {
  const clean = text.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(clean);
} catch(e) {
  parsed = { error: 'Failed to parse AI response', raw: text };
}

const formData = $('Parse Form Input').first().json;

return [{
  json: {
    title: formData.title,
    niche: formData.niche,
    audience: formData.audience,
    postToBuffer: formData.postToBuffer,
    linkedin_posts: parsed.linkedin_posts || [],
    tweets: parsed.tweets || [],
    email_newsletter: parsed.email_newsletter || {},
    content_summary: parsed.content_summary || ''
  }
}];

// Prepare LinkedIn posts for Buffer — one item per post
const d = $input.first().json;
const posts = d.linkedin_posts || [];

return posts.map((post, i) => ({
  json: {
    ...d,
    bufferText: `${post.hook}\n\n${post.body}\n\n${post.cta}\n\n${post.hashtags}`,
    postIndex: i + 1,
    platform: 'linkedin'
  }
}));

// Prepare tweets for Buffer — one item per tweet
const d = $input.first().json;
const tweets = d.tweets || [];

return tweets.map((tweet, i) => ({
  json: {
    ...d,
    bufferText: tweet,
    tweetIndex: i + 1,
    platform: 'twitter'
  }
}));

// Build full Slack draft message with all repurposed content
const d = $input.first().json;

const li = d.linkedin_posts || [];
const tweets = d.tweets || [];
const email = d.email_newsletter || {};
const buffered = d.postToBuffer;

const linkedinSection = li.map((post, i) => {
  return `*LinkedIn Post ${i+1}*
${post.hook}

${post.body}

${post.cta}
${post.hashtags}`;
}).join('

---

');

const tweetSection = tweets.map((t, i) => `${i+1}. ${t}`).join('
');

const emailSection = `*Subject:* ${email.subject_line}
*Preview:* ${email.preview_text}

${email.intro}

${email.body}

*Key Takeaways:*
${(email.key_takeaways || []).map((t, i) => `${i+1}. ${t}`).join('
')}

${email.outro}`;

const bufferStatus = buffered
  ? ':white_check_mark: *Posts scheduled in Buffer — LinkedIn (3 posts, 2 days apart) + Twitter/X (5 tweets, 1 day apart)*'
  : ':pencil: *Draft only — not scheduled. Re-run and select Buffer to auto-post.*';

const slackMessage = `:rocket: *Content Repurposing Pipeline*
*"${d.title}"*
_${d.content_summary}_

${bufferStatus}

${'='.repeat(40)}

:linkedin: *3 LINKEDIN POSTS*

${linkedinSection}

${'='.repeat(40)}

:bird: *5 TWEETS/X POSTS*

${tweetSection}

${'='.repeat(40)}

:email: *EMAIL NEWSLETTER*

${emailSection}

---
_Generated by Content Repurposing Pipeline_`;

return [{
  json: {
    ...d,
    slackMessage
  }
}];

// Build Google Drive document content
const d = $input.first().json;
const li = d.linkedin_posts || [];
const tweets = d.tweets || [];
const email = d.email_newsletter || {};
const date = new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });

const linkedinSection = li.map((post, i) =>
  `LinkedIn Post ${i+1}
${'─'.repeat(30)}
Hook: ${post.hook}

${post.body}

CTA: ${post.cta}
Hashtags: ${post.hashtags}`
).join('

');

const tweetSection = tweets.map((t, i) => `${i+1}. ${t}`).join('

');

const emailSection = `Subject Line: ${email.subject_line}
Preview Text: ${email.preview_text}

Intro:
${email.intro}

Body:
${email.body}

Key Takeaways:
${(email.key_takeaways || []).map((t, i) => `${i+1}. ${t}`).join('
')}

Outro:
${email.outro}`;

const docContent = `CONTENT REPURPOSING REPORT
${'='.repeat(50)}

Title: ${d.title}
Niche: ${d.niche}
Audience: ${d.audience}
Date: ${date}
Buffer Scheduled: ${d.postToBuffer ? 'Yes' : 'No'}
Summary: ${d.content_summary}

${'─'.repeat(50)}
LINKEDIN POSTS (3)
${'─'.repeat(50)}

${linkedinSection}

${'─'.repeat(50)}
TWEETS / X POSTS (5)
${'─'.repeat(50)}

${tweetSection}

${'─'.repeat(50)}
EMAIL NEWSLETTER
${'─'.repeat(50)}

${emailSection}

---
Generated by Content Repurposing Pipeline | ${new Date().toISOString()}`;

return [{
  json: {
    ...d,
    docContent,
    fileName: `Content Repurpose - ${d.title} - ${date}.txt`
  }
}];

const data = $('Parse AI Response').first().json;

return [{
  json: {
    status: 'success',
    title: data.title,
    linkedin_posts_count: 3,
    tweets_count: 5,
    email_generated: true,
    buffer_scheduled: data.postToBuffer,
    slack_sent: true,
    drive_saved: true
  }
}];
